use std::cmp::Ordering;
use std::fmt;

#[derive(Debug, Clone, PartialEq)]
enum Value {
    Int(i64),
    Text(String),
}

impl fmt::Display for Value {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Value::Int(n) => write!(f, "{n}"),
            Value::Text(s) => write!(f, "{s}"),
        }
    }
}

fn compare(a: &Value, b: &Value) -> Ordering {
    match (a, b) {
        (Value::Int(x), Value::Int(y)) => x.cmp(y),
        (Value::Text(x), Value::Text(y)) => x.cmp(y),
        (Value::Int(_), Value::Text(_)) => Ordering::Less,
        (Value::Text(_), Value::Int(_)) => Ordering::Greater,
    }
}

struct Table {
    columns: Vec<String>,
    rows: Vec<Vec<Value>>,
}

fn parse_value(field: &str) -> Value {
    match field.parse::<i64>() {
        Ok(n) => Value::Int(n),
        Err(_) => Value::Text(field.to_string()),
    }
}

fn parse_table(csv: &str) -> Result<Table, String> {
    let mut lines = csv.lines().enumerate().filter(|(_, l)| !l.trim().is_empty());
    let (_, header) = lines.next().ok_or("bad header")?;
    let columns: Vec<String> = header.split(',').map(|c| c.trim().to_string()).collect();
    let mut seen = std::collections::HashSet::new();
    if columns.iter().any(|c| c.is_empty() || !seen.insert(c.clone())) {
        return Err("bad header".to_string());
    }
    let rows = lines
        .map(|(i, line)| {
            let fields: Vec<Value> = line.split(',').map(|f| parse_value(f.trim())).collect();
            if fields.len() == columns.len() { Ok(fields) } else { Err(format!("line {}: expected {} fields", i + 1, columns.len())) }
        })
        .collect::<Result<Vec<_>, _>>()?;
    Ok(Table { columns, rows })
}

#[derive(Debug, Clone, PartialEq)]
enum Tok {
    Word(String),
    Num(i64),
    Str(String),
    Op(String),
    Comma,
    Star,
}

fn tokenize(q: &str) -> Result<Vec<Tok>, String> {
    let bad = || "bad query".to_string();
    let chars: Vec<char> = q.chars().collect();
    let mut toks = Vec::new();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        match c {
            ' ' | '\t' => i += 1,
            ',' => { toks.push(Tok::Comma); i += 1; }
            '*' => { toks.push(Tok::Star); i += 1; }
            '\'' => {
                let end = chars[i + 1..].iter().position(|&x| x == '\'').ok_or_else(bad)? + i + 1;
                toks.push(Tok::Str(chars[i + 1..end].iter().collect()));
                i = end + 1;
            }
            '=' | '!' | '<' | '>' => {
                let two: String = chars[i..(i + 2).min(chars.len())].iter().collect();
                let op = match two.as_str() {
                    "!=" | "<=" | ">=" => two.clone(),
                    _ if c == '!' => return Err(bad()),
                    _ => c.to_string(),
                };
                i += op.len();
                toks.push(Tok::Op(op));
            }
            '0'..='9' | '-' => {
                let start = i;
                i += 1;
                while i < chars.len() && matches!(chars[i], '0'..='9') { i += 1; }
                let text: String = chars[start..i].iter().collect();
                toks.push(Tok::Num(text.parse().map_err(|_| bad())?));
            }
            'a'..='z' | 'A'..='Z' | '_' => {
                let start = i;
                while i < chars.len() && matches!(chars[i], 'a'..='z' | 'A'..='Z' | '0'..='9' | '_') { i += 1; }
                toks.push(Tok::Word(chars[start..i].iter().collect()));
            }
            _ => return Err(bad()),
        }
    }
    Ok(toks)
}

fn run(table: &Table, query: &str) -> Result<Vec<String>, String> {
    let toks = tokenize(query)?;
    let mut pos = 0;
    let keyword = |t: Option<&Tok>, k: &str| matches!(t, Some(Tok::Word(w)) if w.eq_ignore_ascii_case(k));
    let column = |name: &str| table.columns.iter().position(|c| c == name).ok_or(format!("unknown column {name}"));
    let bad = || "bad query".to_string();

    if !keyword(toks.get(pos), "select") { return Err(bad()); }
    pos += 1;

    let selected: Vec<usize> = if toks.get(pos) == Some(&Tok::Star) {
        pos += 1;
        (0..table.columns.len()).collect()
    } else {
        let mut cols = Vec::new();
        loop {
            match toks.get(pos) {
                Some(Tok::Word(w)) if !["where", "order", "limit"].iter().any(|k| w.eq_ignore_ascii_case(k)) => cols.push(column(w)?),
                _ => return Err(bad()),
            }
            pos += 1;
            if toks.get(pos) != Some(&Tok::Comma) { break; }
            pos += 1;
        }
        cols
    };

    let mut filter: Box<dyn Fn(&[Value]) -> bool> = Box::new(|_| true);
    if keyword(toks.get(pos), "where") {
        let (Some(Tok::Word(col)), Some(Tok::Op(op)), Some(val)) = (toks.get(pos + 1), toks.get(pos + 2), toks.get(pos + 3)) else {
            return Err(bad());
        };
        let idx = column(col)?;
        let target = match val {
            Tok::Num(n) => Value::Int(*n),
            Tok::Str(s) => Value::Text(s.clone()),
            _ => return Err(bad()),
        };
        let wanted: Vec<Ordering> = match op.as_str() {
            "=" => vec![Ordering::Equal],
            "!=" => vec![Ordering::Less, Ordering::Greater],
            "<" => vec![Ordering::Less],
            ">" => vec![Ordering::Greater],
            "<=" => vec![Ordering::Less, Ordering::Equal],
            _ => vec![Ordering::Greater, Ordering::Equal],
        };
        filter = Box::new(move |row| wanted.contains(&compare(&row[idx], &target)));
        pos += 4;
    }

    let mut order: Option<(usize, bool)> = None;
    if keyword(toks.get(pos), "order") {
        if !keyword(toks.get(pos + 1), "by") { return Err(bad()); }
        let Some(Tok::Word(col)) = toks.get(pos + 2) else { return Err(bad()) };
        let idx = column(col)?;
        pos += 3;
        let desc = if keyword(toks.get(pos), "desc") { pos += 1; true } else { if keyword(toks.get(pos), "asc") { pos += 1; } false };
        order = Some((idx, desc));
    }

    let mut limit = usize::MAX;
    if keyword(toks.get(pos), "limit") {
        match toks.get(pos + 1) {
            Some(Tok::Num(n)) if *n >= 0 => limit = *n as usize,
            _ => return Err("bad limit".to_string()),
        }
        pos += 2;
    }
    if pos != toks.len() { return Err(bad()); }

    let mut rows: Vec<&Vec<Value>> = table.rows.iter().filter(|r| filter(r)).collect();
    if let Some((idx, desc)) = order {
        rows.sort_by(|a, b| if desc { compare(&b[idx], &a[idx]) } else { compare(&a[idx], &b[idx]) });
    }
    let header = selected.iter().map(|&i| table.columns[i].as_str()).collect::<Vec<_>>().join(" | ");
    Ok(std::iter::once(header)
        .chain(rows.into_iter().take(limit).map(|r| selected.iter().map(|&i| r[i].to_string()).collect::<Vec<_>>().join(" | ")))
        .collect())
}

