let csv = "name,city,age\nAda,London,36\nGrace,New York,85\nLinus,Helsinki,55\nAlan,London,41\n";
let table = parse_table(csv).unwrap();

test("parsing tables", || {
    check_eq(table.columns.clone(), vec!["name", "city", "age"]);
    check_eq(table.rows.len(), 4);
    check_eq(table.rows[1][2].clone(), Value::Int(85));
    check_eq(table.rows[1][1].clone(), Value::Text("New York".to_string()));
    check_eq(parse_table("a,b\n1,2,3").err(), Some("line 2: expected 2 fields".to_string()));
    check_eq(parse_table("a,a\n1,2").err(), Some("bad header".to_string()));
    check_eq(parse_table("").err(), Some("bad header".to_string()));
    check_eq(parse_table("\nx\n\n5\n").map(|t| t.rows.len()), Ok(1));
});

test("select and where", || {
    check_eq(run(&table, "select name, age where age > 40 order by age desc"),
             Ok(vec!["name | age".to_string(), "Grace | 85".to_string(), "Linus | 55".to_string(), "Alan | 41".to_string()]));
    check_eq(run(&table, "SELECT * WHERE city = 'London'").unwrap(),
             vec!["name | city | age", "Ada | London | 36", "Alan | London | 41"]);
    check_eq(run(&table, "select name where city != 'London' order by name").unwrap(), vec!["name", "Grace", "Linus"]);
    check_eq(run(&table, "select name where age <= 41 order by age").unwrap(), vec!["name", "Ada", "Alan"]);
    check_eq(run(&table, "select name where name >= 'H'").unwrap(), vec!["name", "Linus"]);
    check_eq(run(&table, "select name where age = 'old'").unwrap(), vec!["name"]);
});

test("ordering and limits", || {
    check_eq(run(&table, "select city, name order by city limit 3").unwrap(),
             vec!["city | name", "Helsinki | Linus", "London | Ada", "London | Alan"]);
    check_eq(run(&table, "select name limit 0").unwrap(), vec!["name"]);
    check_eq(run(&table, "select age order by age asc limit 2").unwrap(), vec!["age", "36", "41"]);
});

test("errors", || {
    check_eq(run(&table, "select salary"), Err("unknown column salary".to_string()));
    check_eq(run(&table, "select name where height > 3"), Err("unknown column height".to_string()));
    check_eq(run(&table, "select name limit -1"), Err("bad limit".to_string()));
    check_eq(run(&table, "select name limit lots"), Err("bad limit".to_string()));
    for q in ["", "name", "select", "select name where age >", "select name where age ~ 3",
              "select name order age", "select name where city = 'London", "select name extra", "select name,"] {
        check_eq(run(&table, q), Err("bad query".to_string()));
    }
});

